function roleFor(repo, user) {
    if (!repo || !user) return null;
    if (repo.ownerType === 'user') return repo.ownerId === user.id ? 'Admin' : directRole(repo, user, null);
    const org = orgFor(repo);
    if (!org) return directRole(repo, user, null);
    const m = orgMemberOf(org.id, user.id);
    if (m && m.role === 'Owner') return 'Admin';
    return directRole(repo, user, org.id);
  }

function orgMemberOf(orgId, userId) {
    return (st().orgMembers || []).find((m) => m.orgId === orgId && m.userId === userId) || null;
  }

function directRole(repo, user, orgId) {
    let best = null;
    const teams = orgId ? teamIdsFor(user.id, orgId) : [];
    for (const g of st().grants || []) {
      if (g.repoId !== repo.id) continue;
      const match = (g.kind === 'user' && g.subjectId === user.id) || (g.kind === 'team' && teams.indexOf(g.subjectId) !== -1);
      if (match && (!best || RANK[g.role] > RANK[best])) best = g.role;
    }
    return best;
  }

function teamIdsFor(userId, orgId) {
    return (st().teamMembers || [])
      .filter((m) => m.userId === userId && ((byId('teams', m.teamId) || {}).orgId === orgId))
      .map((m) => m.teamId);
  }

