function mergeBlocked(pr, repo) {
    const rule = protectionFor(repo.id, pr.base);
    if (hasRequestChanges(pr)) return 'Changes requested';
    if (rule && rule.requireApproval && approvalCount(pr) < 1) return 'Review required by branch protection';
    if (rule && rule.requireCheck) {
      const chk = (st().checks || []).find((c) => c.prId === pr.id && c.name === 'test');
      if (!chk || chk.status !== 'success') return 'Required check test is not success';
    }
    return null;
  }

function protectionFor(repoId, branch) {
    return (st().protectionRules || []).find((r) => r.repoId === repoId && r.branch === branch) || null;
  }

function hasRequestChanges(pr) {
    const seen = {};
    for (const rv of st().reviews || []) { if (rv.prId === pr.id) seen[rv.reviewer] = rv; }
    return Object.keys(seen).some((k) => seen[k].state === 'Changes requested');
  }

function approvalCount(pr) {
    // A review decision is only valid for the CURRENT compare commit: when the compare branch gains a
    // new commit every earlier decision becomes stale and a fresh non-author Approve is required.
    const head = branchHead(pr.repoId, pr.compare);
    const seen = {};
    if (!head) return 0;
    for (const rv of st().reviews || []) {
      if (rv.prId !== pr.id) continue;
      seen[rv.reviewer] = rv;
    }
    let n = 0;
    Object.keys(seen).forEach((k) => {
      const rv = seen[k];
      if (rv.state !== 'Approved' || rv.reviewer === pr.author) return;
      if (rv.commitId !== head) return;
      n += 1;
    });
    return n;
  }

function branchHead(repoId, branch) {
    const b = (st().branches || []).find((x) => x.repoId === repoId && x.name === branch);
    return b ? b.commitId : null;
  }
